{  ${34 \left( m \right) }$ }
   { ${35 \left( m \right) }$  }
     { ${37 \left( m \right) } $  }
    { \True  ${36  \left( m \right) } $ }
}{
\begin{tikzpicture}[font=\footnotesize, line join=round, line cap=round, >=stealth]
    \tikzset{Cay-tre/.pic={
            \tikzset{la/.pic={
                    \fill[green!80!white](0,0)..controls++(-20:0.5) and ++(-175:1)..(2,0)..controls++(170:1) and ++(20:0.5)..(0,0);
            } }
            \def\cao{4}
            \def\a{0.1*\cao}
            \def\k{0.5}% Hệ số góc
            \pgfmathsetmacro{\dai}{\cao*\k}
            \draw[fill=green!75!blue,draw=teal](0,0)rectangle(\a,\cao)pic[rotate=20]{la};
            \draw[fill=green!70!blue,draw=teal](-\dai,0)--(0,\cao)coordinate(cao)--([turn]90:\a)--([turn]90:{2/.9*\dai})--cycle;
            \draw[teal](-\dai,0)coordinate(dai)--(0,0)coordinate(oo);
            \begin{scope}
                \clip(oo)--(cao)--(dai)--cycle;
            \end{scope}
